<script setup lang="ts">
import { computed, onMounted, ref } from 'vue'
import { RouterLink } from 'vue-router'
import PortfolioShell from '@/components/PortfolioShell.vue'
import { bi, l, say } from '@/content/portfolio'
type Demo = { recorded:string; cv:string; job:string; job_title:string; company:string;
  match:{ match_score:number; verdict_reason:string; matched_items:{requirement:string;resume_evidence:string}[]; missing_items:{requirement:string;explanation:string}[]; improvements:string[] };
  sections:{title:string;items:{source:string;suggestion:string|null}[]}[];
  preparation:{summary:string;items:{title:string;focus:string;question:string;outline:string[]}[]}; trace:{tool:string}[] }
const demo = ref<Demo|null>(null), failed = ref(false), loading = ref(false), tab = ref(0)
const tabs = [bi('The input', '输入资料'), bi('Role analysis', '岗位分析'), bi('CV & exports', '简历与导出'), bi('Interview plan', '面试准备')]
const tools: Record<string,string> = {analyze_job:'Analyse the role',tailor_resume:'Prepare the CV',prepare_interview:'Prepare for interviews',finish:'Complete the task'}
const toolsZh: Record<string,string> = {analyze_job:'分析岗位',tailor_resume:'准备简历',prepare_interview:'准备面试',finish:'完成任务'}
const suggestions = computed(()=>demo.value?.sections.flatMap(s=>s.items).filter(i=>i.suggestion).length||0)
async function load() {
  loading.value=true; failed.value=false
  try { const response=await fetch('/demo/recorded-run.json'); if(!response.ok) throw new Error(); const value=await response.json(); if(!value.match || !value.preparation || !Array.isArray(value.sections)) throw new Error(); demo.value=value }
  catch { failed.value=true } finally { loading.value=false }
}
function navigateTabs(event:KeyboardEvent) {
  const keys=['ArrowLeft','ArrowRight','Home','End']; if(!keys.includes(event.key)) return
  event.preventDefault(); tab.value=event.key==='Home'?0:event.key==='End'?tabs.length-1:(tab.value+(event.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length
  document.getElementById('demo-tab-'+tab.value)?.focus()
}
onMounted(load)
</script>
<template>
  <PortfolioShell>
    <div class="demo-main">
      <div class="breadcrumbs"><RouterLink to="/">{{ say('AI Studio', 'AI 工作室') }}</RouterLink> / {{ say('Recorded example', '预生成示例') }}</div>
      <div class="demo-intro"><div><span class="portfolio-eyebrow">{{ say('NO ACCOUNT. NO UPLOAD. NO WAIT FOR AI.', '无需账号、无需上传、无需等待 AI。') }}</span><h1>{{ say('A career task, from start to finish.', '一项求职任务，从输入到成果。') }}</h1><p>{{ say('Explore an actual model-generated result using a fictional CV and job description. This is a saved, read-only example, not a live AI session or Tianyu’s own CV.', '使用虚构简历与岗位要求，查看实际模型生成的成果。这是已保存的只读示例，不是实时 AI 会话，也不是齐天宇本人的简历。') }}</p></div><RouterLink to="/agent" class="portfolio-button secondary">{{ say('Use my own CV', '使用自己的简历') }} ↗</RouterLink></div>
      <div v-if="loading" role="status" class="demo-status">{{ say('Loading the saved example…', '正在载入已保存的示例……') }}</div>
      <div v-else-if="failed" role="alert" class="demo-status"><p>{{ say('The saved example could not be loaded. Please try again.', '示例暂时无法载入，请重试。') }}</p><button @click="load" class="portfolio-button">{{ say('Retry', '重试') }}</button></div>
      <template v-else-if="demo">
        <div class="demo-meta"><span class="portfolio-pill">{{ say('RECORDED EXAMPLE · READ ONLY', '预生成示例 · 只读') }}</span><span>{{ say('Fictional applicant: Alex Morgan', '虚构申请者：Alex Morgan') }}</span><span>{{ say('Recorded', '生成日期') }} {{ demo.recorded }}</span></div>
        <div class="demo-tabs" role="tablist" :aria-label="say('Example outcomes', '示例成果')" @keydown="navigateTabs"><button v-for="(label,i) in tabs" :key="i" :id="'demo-tab-'+i" role="tab" :aria-selected="tab===i" :tabindex="tab===i?0:-1" :aria-controls="'demo-panel-'+i" @click="tab=i"><span>0{{ i+1 }}</span>{{ l(label) }}</button></div>
        <div :id="'demo-panel-'+tab" role="tabpanel" :aria-labelledby="'demo-tab-'+tab" tabindex="0" class="demo-panel">
          <div v-if="tab===0" class="demo-input-grid"><section><span class="portfolio-eyebrow">{{ say('SOURCE CV · FICTIONAL', '原始简历 · 虚构资料') }}</span><h2>Alex Morgan</h2><pre>{{ demo.cv }}</pre></section><section><span class="portfolio-eyebrow">{{ say('TARGET ROLE · FICTIONAL', '目标岗位 · 虚构岗位') }}</span><h2>{{ demo.job_title }}</h2><span class="portfolio-pill">{{ demo.company }}</span><p>{{ demo.job }}</p><div class="demo-note">{{ say('Notice the deliberate gap: PostgreSQL is requested in the job description but is not evidenced in the CV. The output should acknowledge that gap, not invent experience.', '注意这个刻意设置的缺口：岗位提到 PostgreSQL，但简历没有相关证据。输出应承认缺口，而不是编造经历。') }}</div><button class="portfolio-button" @click="tab=1">{{ say('See the analysis', '查看分析结果') }} →</button></section></div>
          <section v-else-if="tab===1"><div class="score-summary"><div class="demo-score"><strong>{{ demo.match.match_score }}<small>/100</small></strong><span>{{ say('Heuristic match score', '启发式匹配评分') }}</span></div><div><h2>{{ say('Evidence before assumptions.', '用证据说明匹配。') }}</h2><p>{{ demo.match.verdict_reason }}</p><small>{{ say('This score is not a hiring probability or a validated accuracy metric.', '此分数不是录用概率，也不是经验证的准确率指标。') }}</small></div></div><div class="demo-input-grid"><section><h3>{{ say('Evidence in the CV', '简历中的证据') }}</h3><article v-for="item in demo.match.matched_items" :key="item.requirement" class="evidence-item"><h4>{{ item.requirement }}</h4><blockquote>{{ item.resume_evidence }}</blockquote></article></section><section><h3>{{ say('Not yet evidenced', '尚未提供的证据') }}</h3><article v-for="item in demo.match.missing_items" :key="item.requirement" class="gap-item"><h4>{{ item.requirement }}</h4><p>{{ item.explanation }}</p></article><h3>{{ say('Next steps', '下一步建议') }}</h3><ul class="demo-list"><li v-for="item in demo.match.improvements" :key="item">{{ item }}</li></ul></section></div></section>
          <section v-else-if="tab===2"><div class="demo-result-heading"><div><h2>{{ say('A document you can take away.', '可以直接带走的文档。') }}</h2><p>{{ say('Actual PDF and editable Word exports from the fictional task.', '来自这项虚构资料任务的实际 PDF 与可编辑 Word 导出。') }}</p></div><div class="portfolio-actions"><a href="/demo/sample-cv.pdf" download="fictional-example-cv.pdf" class="portfolio-button">PDF ↓</a><a href="/demo/sample-cv.docx" download="fictional-example-cv.docx" class="portfolio-button secondary">Word ↓</a></div></div><div v-if="!suggestions" class="demo-note">{{ say('In this run, no proposed rewrite passed the meaningful-change filter. The original wording was retained. This is an intentional quality boundary: do not manufacture improvements just to fill a suggestions list.', '本次执行中，没有改写通过实质变化筛选，因此保留原文。这是明确的质量边界：不为了填满建议列表而制造无效修改。') }}</div><div v-for="section in demo.sections" :key="section.title" class="sample-section"><h3>{{ section.title }}</h3><article v-for="item in section.items" :key="item.source"><span class="portfolio-pill">{{ item.suggestion?say('Suggested wording', '建议表达'):say('Original retained', '保留原文') }}</span><p>{{ item.source }}</p><p v-if="item.suggestion" class="suggested-wording">{{ item.suggestion }}</p></article></div><p class="sample-footnote">{{ say('The live app lets users accept, reject or edit suggestions. This recorded view cannot change a real user’s documents.', '实际应用支持采纳、保留或自行编辑建议。这个只读示例不会修改任何用户的真实文档。') }}</p></section>
          <section v-else><h2>{{ say('Prepare first. Practise when ready.', '先准备，再自主选择练习。') }}</h2><p>{{ demo.preparation.summary }}</p><details v-for="(item,i) in demo.preparation.items" :key="item.title" class="preparation-item" :open="i===0"><summary><span>0{{ i+1 }}</span>{{ item.title }}</summary><div><p>{{ item.focus }}</p><h4>{{ say('Practice question', '练习问题') }}</h4><blockquote>{{ item.question }}</blockquote><h4>{{ say('Answer outline', '回答思路') }}</h4><ul class="demo-list"><li v-for="line in item.outline" :key="line">{{ line }}</li></ul></div></details><div class="demo-note">{{ say('These are preparation prompts, not verified company interview questions. Suggested technologies are not added to the applicant’s CV as claimed experience.', '这些是准备提示，不是经过验证的企业面试真题。建议学习的技术不会被作为已有经历加入简历。') }}</div></section>
        </div>
        <details class="execution-note"><summary>{{ say('How this example ran', '这份示例如何生成') }}</summary><ol><li v-for="(step,i) in demo.trace" :key="i">{{ say(tools[step.tool]||step.tool,toolsZh[step.tool]||step.tool) }} <code>{{ step.tool }}</code></li></ol><p>{{ say('These are recorded tool names, not hidden model reasoning. The server limited the available actions and saved each completed outcome. This single run is not a performance benchmark.', '这里展示的是实际工具名称，不是模型隐含推理。服务端限制可选操作并保存每步成果。这一次执行不能作为性能基准。') }}</p></details>
        <p class="demo-language-note">{{ say('The recorded source material and model outputs are in English. Interface labels switch language; the saved evidence is kept unchanged.', '本次记录的原始资料及模型输出为英文。界面标签支持语言切换，已保存的证据内容保持原样。') }}</p>
        <div class="project-bottom"><RouterLink to="/projects/career-agent" class="text-link">{{ say('Read the technical case study', '阅读技术项目介绍') }} →</RouterLink><RouterLink to="/agent" class="portfolio-button">{{ say('Start my own career task', '开始自己的求职任务') }} ↗</RouterLink></div>
      </template>
    </div>
  </PortfolioShell>
</template>
<style scoped>
.demo-main{padding-block:35px 65px}.demo-intro{display:flex;align-items:center;justify-content:space-between;gap:35px;margin-bottom:25px}.demo-intro>div{max-width:800px}.demo-intro h1{font-size:clamp(30px,4vw,46px);font-weight:600;letter-spacing:-1.5px;line-height:1.2;margin-bottom:19px}.demo-intro p{font-size:14px;color:var(--soft);margin:0}.demo-intro>a{flex-shrink:0}.demo-meta{display:flex;align-items:center;flex-wrap:wrap;gap:15px;font-size:11px;color:var(--soft);padding-block:17px}.demo-tabs{display:flex;margin-top:12px;border:1px solid var(--border);border-radius:12px 12px 0 0;overflow:hidden;background:#eaf0e1}.demo-tabs button{border:0;border-right:1px solid #d0dcc5;padding:17px 15px;background:none;color:#486144;font-size:13px;flex:1;line-height:1.5}.demo-tabs button[aria-selected=true]{background:#294d3b;color:#fff}.demo-tabs button>span{font-size:10px;margin-right:9px;opacity:.8}.demo-panel{padding:32px;border:1px solid var(--border);border-top:0;border-radius:0 0 12px 12px;background:#fffefa;min-height:480px}.demo-panel h2{font-size:25px;font-weight:600;letter-spacing:-.5px;line-height:1.35}.demo-panel h3{font-size:17px;font-weight:600}.demo-panel h4{font-size:13px;font-weight:600;margin:0 0 9px}.demo-panel p{font-size:14px;color:var(--soft);line-height:1.85}.demo-input-grid{display:grid;grid-template-columns:1fr 1fr;gap:35px}.demo-input-grid section>p{margin-top:17px}.demo-input-grid pre{white-space:pre-wrap;font:inherit;font-size:13px;line-height:2;color:#40584a;background:#f0f4e9;padding:23px;border:1px solid #d8e2ce;border-radius:10px;overflow-wrap:anywhere}.demo-note{padding:18px 20px;background:#f2efdf;border:1px solid #e0d9bd;border-radius:9px;color:#655938;font-size:13px;line-height:1.85;margin:20px 0}.score-summary{display:flex;align-items:center;gap:28px;margin-bottom:30px;padding-bottom:30px;border-bottom:1px solid var(--border)}.score-summary h2{margin-bottom:12px}.score-summary p{margin:0 0 9px}.score-summary small{font-size:11px;color:#6a725e}.demo-score{padding:25px 17px;min-width:175px;text-align:center;background:#e9efdd;border-radius:12px}.demo-score strong{font-size:43px;font-weight:550;display:block;line-height:1.3}.demo-score strong small{font-size:16px}.demo-score>span{font-size:11px;color:#4d6345}.evidence-item{border-bottom:1px solid var(--border);padding:15px 0}.evidence-item blockquote{font-size:13px;border-left:2px solid #9fb384;padding-left:14px;margin:0;color:var(--soft);line-height:1.8}.gap-item{padding:18px;background:#f1ebda;border-radius:9px;margin-bottom:25px}.gap-item p{margin:0;font-size:13px}.demo-list{padding-left:20px;color:var(--soft);font-size:13px;line-height:1.9}.demo-list li{padding-bottom:7px}.demo-result-heading{display:flex;justify-content:space-between;align-items:center;gap:20px}.demo-result-heading h2{margin-bottom:10px}.demo-result-heading p{margin:0}.sample-section{margin-top:30px;padding-top:22px;border-top:1px solid var(--border)}.sample-section article{margin:15px 0}.sample-section p{margin:10px 0}.sample-footnote,.demo-language-note{font-size:12px!important;color:var(--soft);line-height:1.8}.suggested-wording{padding:15px;background:#edf3e5}.preparation-item{border:1px solid var(--border);border-radius:10px;margin-top:14px;overflow:hidden}.preparation-item summary{padding:18px 20px;cursor:pointer;font-size:14px;font-weight:600;list-style:none;background:#f0f4e8}.preparation-item summary::after{content:'+';float:right;margin-left:12px}.preparation-item[open] summary::after{content:'−'}.preparation-item summary>span{font-size:11px;color:#516e42;margin-right:12px}.preparation-item>div{padding:20px 25px}.preparation-item blockquote{margin:12px 0 20px;padding:15px;border-left:3px solid #a0b487;background:#f6f7ef;font-size:14px;color:var(--soft)}.execution-note{border:1px solid var(--border);border-radius:10px;padding:18px 22px;margin-top:22px;font-size:13px;color:var(--soft)}.execution-note summary{cursor:pointer;font-weight:600;color:var(--ink)}.execution-note li{margin:10px 0}.execution-note code{font-size:11px;background:#edf1e6;border-radius:4px;padding:3px 6px;margin-left:12px}.execution-note p{margin-bottom:0}.demo-language-note{margin-top:18px}.demo-status{padding:35px;background:white;border:1px solid var(--border);border-radius:10px}
@media(max-width:850px){.demo-intro{align-items:flex-start;flex-direction:column;gap:20px}.demo-input-grid{grid-template-columns:1fr;gap:20px}.demo-result-heading{align-items:flex-start;flex-direction:column}.demo-panel{padding:22px}.demo-tabs button{font-size:12px;padding:14px 8px}.demo-tabs button>span{display:block;margin-right:0;margin-bottom:5px}}
@media(max-width:480px){.score-summary{align-items:flex-start;flex-direction:column;gap:20px}.demo-score{padding:12px 22px}.demo-score strong{font-size:32px}.demo-panel{padding:18px}.demo-panel h2{font-size:23px}.demo-intro h1{font-size:33px}.demo-input-grid pre{padding:15px}.preparation-item summary{padding:15px}.preparation-item>div{padding:15px}.demo-tabs button{font-size:11px}.demo-meta{gap:10px}.execution-note{padding:15px}.execution-note code{display:block;width:fit-content;margin:5px 0}}
</style>
